<script setup>
import { reactive, watch } from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MTextarea from '../../../components/mds/MTextarea.vue';
import { financialDraft, financialPayload, financialSchema } from '../domain/partner-financial-write.mjs';
const props = defineProps({ entity: String, record: Object, saving: Boolean, error: String }); const emit = defineEmits(['back', 'save']); const schema = financialSchema(props.entity); const draft = reactive({ ...financialDraft(props.entity, props.record) }); watch(() => props.record, (record) => Object.assign(draft, financialDraft(props.entity, record)));
function submit() { try { emit('save', financialPayload(props.entity, draft, { existing: props.record })); } catch (error) { emit('local-error', error.message); } }
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[760px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" @submit.prevent="submit"><header class="flex items-start justify-between gap-3 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold">{{ record ? 'Sửa' : 'Thêm' }} {{ schema.label }}</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Máy chủ kiểm tra lại quyền và dữ liệu Confidential khi lưu.</p></div><MButton variant="neutral" @click="emit('back')">Hủy</MButton></header><div class="grid gap-4 p-5 sm:grid-cols-2"><label v-for="field in schema.fields" :key="field.key" :class="field.multiline?'sm:col-span-2':''"><span class="mb-1 block text-[13px] font-medium">{{ field.label }}<template v-if="field.required"> *</template></span><MTextarea v-if="field.multiline" v-model="draft[field.key]" :rows="3"/><MInput v-else v-model="draft[field.key]" :type="field.type||'text'" :inputmode="field.type==='number'?'decimal':undefined" :required="field.required"/></label></div><p v-if="error" role="alert" class="mx-5 mb-4 text-[13px] text-[var(--mds-danger)]">{{ error }}</p><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="saving" @click="emit('back')">Hủy</MButton><MButton type="submit" variant="primary" :loading="saving">Lưu</MButton></footer></form></section></template>
